#!/bin/bash
# Configuration script for Chat Simulator
# This script updates environment variables based on port configuration

# Default ports
PYTHON_PORT=${PYTHON_PORT:-5000}
FRONTEND_PORT=${FRONTEND_PORT:-5173}

# Update .env.local file
cat > .env.local << EOF
# Chat Simulator Configuration
# Generated by smart startup scripts

# Python GIF Generator Configuration
VITE_PYTHON_API_URL=http://localhost:$PYTHON_PORT
VITE_PYTHON_HEALTH_URL=http://localhost:$PYTHON_PORT/health
VITE_PYTHON_LOGS_URL=http://localhost:$PYTHON_PORT/logs

# Frontend Configuration
VITE_PORT=$FRONTEND_PORT
PORT=$FRONTEND_PORT

# Service Status
PYTHON_PORT=$PYTHON_PORT
FRONTEND_PORT=$FRONTEND_PORT
EOF

echo "Configuration updated:"
echo "  Python API: http://localhost:$PYTHON_PORT"
echo "  Frontend: http://localhost:$FRONTEND_PORT"
